parameters.jsCode:
const ticket = $('Webhook').first().json.body || {};
const raw = $input.first().json;
let ai = {};
try {
  ai = JSON.parse(raw.candidates[0].content.parts[0].text);
} catch (e) {
  ai = {};
}
const cats = ['technical_issue', 'billing', 'sales', 'general', 'spam'];
const urgs = ['low', 'medium', 'high'];
const score = Number.isInteger(ai.priority_score) && ai.priority_score >= 1 && ai.priority_score <= 10 ? ai.priority_score : 5;
return [{
  json: {
    name: String(ticket.name || '').slice(0, 100),
    email: String(ticket.email || '').slice(0, 200),
    message: String(ticket.message || '').slice(0, 2000),
    category: cats.includes(ai.category) ? ai.category : 'general',
    urgency: urgs.includes(ai.urgency) ? ai.urgency : 'medium',
    priority_score: score,
    summary: String(ai.summary || 'AI result could not be parsed').slice(0, 200),
    ai_ok: cats.includes(ai.category)
  }
}];
